import 'package:flutter/material.dart';
import '../../services/local_environment.dart';
class DatabasePage extends StatefulWidget{const DatabasePage({super.key});@override State<DatabasePage> createState()=>_DatabasePageState();}
class _DatabasePageState extends State<DatabasePage>{final sql=TextEditingController(text:'SELECT name FROM sqlite_master WHERE type = \'table\';');List<Map<String,Object?>> rows=[];String? error;bool busy=false;@override void initState(){super.initState();LocalEnvironment.instance.initialize().then((_)=>_run());}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Database')),body:ListView(padding:const EdgeInsets.all(18),children:[const Card(child:ListTile(leading:Icon(Icons.storage,color:Color(0xffa3ff12)),title:Text('SQLite'),subtitle:Text('Local database · default.db'))),const SizedBox(height:14),const Text('SQL EDITOR',style:TextStyle(letterSpacing:1.4,color:Colors.white60)),const SizedBox(height:8),TextField(controller:sql,minLines:5,maxLines:10,style:const TextStyle(fontFamily:'monospace'),decoration:const InputDecoration(border:OutlineInputBorder(),hintText:'Enter SQL')),const SizedBox(height:10),FilledButton.icon(onPressed:busy?null:_run,icon:const Icon(Icons.play_arrow),label:const Text('Run query')),if(error!=null)Padding(padding:const EdgeInsets.all(8),child:Text(error!,style:const TextStyle(color:Colors.redAccent))),...rows.isEmpty?[]:[SingleChildScrollView(scrollDirection:Axis.horizontal,child:DataTable(columns:rows.first.keys.map((k)=>DataColumn(label:Text(k))).toList(),rows:rows.map((r)=>DataRow(cells:r.values.map((v)=>DataCell(Text('$v'))).toList())).toList()))]));Future<void> _run()async{setState(()=>busy=true);try{final result=await LocalEnvironment.instance.query(sql.text);setState((){rows=result;error=null;busy=false;});}catch(e){setState((){error='$e';rows=[];busy=false;});}}}
